pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.roll(15);
        vm.warp(1);
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success);
        assertTrue(address(c).balance == 0 ether, "Contract balance should be 0 after correct transfer");
    }
}
